      POSTGRES_USER: ${POSTGRES_USER:-yt}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD}
      POSTGRES_DB: ${POSTGRES_DB:-yt}
    volumes:
      - pgdata:/var/lib/postgresql/data
    ports:
      - '127.0.0.1:5432:5432'
    healthcheck:
      test: ['CMD-SHELL', 'pg_isready -U ${POSTGRES_USER:-yt}']
      interval: 5s
      retries: 5

  seaweedfs:
    image: chrislusf/seaweedfs:4.53
    entrypoint: ['/bin/sh', '/etc/seaweedfs/entrypoint.sh']
    environment:
      S3_ACCESS_KEY: ${S3_ACCESS_KEY:-admin}
      S3_SECRET_KEY: ${S3_SECRET_KEY:-dev_secret_key}
    volumes:
      - seaweedfs_data:/data
      - ./docker/seaweedfs/entrypoint.sh:/etc/seaweedfs/entrypoint.sh:ro
    healthcheck:
      test: ['CMD-SHELL', 'wget -qO- http://localhost:8333/ || exit 1']
      interval: 5s
      retries: 10

  api:
    build:
      context: ./backend
      args:
        MODE: api
    env_file: .env
    environment:
      MODE: api
      DATABASE_URL: ${DATABASE_URL:-postgresql+asyncpg://yt:change_me@db:5432/yt}
      S3_ENDPOINT: ${S3_ENDPOINT:-seaweedfs:8333}
      S3_ACCESS_KEY: ${S3_ACCESS_KEY:-admin}
      S3_SECRET_KEY: ${S3_SECRET_KEY:-dev_secret_key}
      S3_BUCKET: ${S3_BUCKET:-videos}
      S3_REGION: ${S3_REGION:-us-east-1}
      JWT_SECRET: ${JWT_SECRET}
      REFRESH_SECRET: ${REFRESH_SECRET}
      COOKIE_SECURE: ${COOKIE_SECURE:-false}
      CORS_ORIGINS: ${CORS_ORIGINS:-http://localhost}
      UPLOAD_MAX_SIZE: ${UPLOAD_MAX_SIZE:-524288000}
      ACCESS_TOKEN_MINUTES: ${ACCESS_TOKEN_MINUTES:-15}
      REFRESH_TOKEN_DAYS: ${REFRESH_TOKEN_DAYS:-30}
      LOG_LEVEL: ${LOG_LEVEL:-INFO}
    volumes:
      - ./backend:/app:ro
    depends_on:
      db:
        condition: service_healthy
      seaweedfs:
        condition: service_healthy

  worker:
    build:
      context: ./backend
      args:
        MODE: worker
    env_file: .env
    environment:
      MODE: worker
      DATABASE_URL: ${DATABASE_URL:-postgresql+asyncpg://yt:change_me@db:5432/yt}
      S3_ENDPOINT: ${S3_ENDPOINT:-seaweedfs:8333}
      S3_ACCESS_KEY: ${S3_ACCESS_KEY:-admin}
      S3_SECRET_KEY: ${S3_SECRET_KEY:-dev_secret_key}
      S3_BUCKET: ${S3_BUCKET:-videos}
      S3_REGION: ${S3_REGION:-us-east-1}
      JWT_SECRET: ${JWT_SECRET}
      REFRESH_SECRET: ${REFRESH_SECRET}
      LOG_LEVEL: ${LOG_LEVEL:-INFO}
    depends_on:
      db:
        condition: service_healthy
      seaweedfs:
        condition: service_healthy

  nginx:
    image: nginx:alpine
    ports:
      - '${NGINX_PORT:-80}:80'
    volumes:
      - ./docker/nginx/nginx.conf:/etc/nginx/nginx.conf:ro
    depends_on:
      - api
      - seaweedfs

volumes:
  pgdata:
  seaweedfs_data:

worker_processes auto;

events { worker_connections 1024; }

http {
    include       mime.types;
    default_type  application/octet-stream;
    sendfile      on;
    keepalive_timeout 65;

    upstream api_upstream      { server api:8000; }
    upstream seaweedfs_upstream { server seaweedfs:8333; }

    server {
        listen 80;
        client_max_body_size 524288000;

        location /api/ {
            proxy_pass http://api_upstream;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
        }

        location /docs {
            proxy_pass http://api_upstream/docs;
            proxy_set_header Host $host;
        }
        location /redoc {
            proxy_pass http://api_upstream/redoc;
            proxy_set_header Host $host;
        }
        location /openapi.json {
            proxy_pass http://api_upstream/openapi.json;
            proxy_set_header Host $host;
        }

        location /storage/ {
            proxy_pass http://seaweedfs_upstream/;
            proxy_set_header Host seaweedfs:8333;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_buffering off;
            proxy_request_buffering off;
            add_header Access-Control-Allow-Origin * always;
            add_header Access-Control-Allow-Methods 'GET, PUT, OPTIONS' always;
            add_header Access-Control-Allow-Headers 'Range' always;
            if ($request_method = 'OPTIONS') {
                return 204;
            }
        }

        location / {
            proxy_pass http://host.docker.internal:5173;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection "upgrade";
        }
    }
}
